function Card({ children, className = "" }: { children: ReactNode; className?: string }) {
  return <section className={`card ${className}`}>{children}</section>;
}

function CardHeader({ title, description, icon, action }: { title: string; description?: string; icon?: ReactNode; action?: ReactNode }) {
  return <div className="card-header"><div><h2 className="card-title">{icon && <span className="icon-box">{icon}</span>}{title}</h2>{description && <p className="card-description">{description}</p>}</div>{action}</div>;
}

function Badge({ children, tone = "blue" }: { children: ReactNode; tone?: "green" | "amber" | "red" | "blue" | "purple" }) {
  return <span className={`badge ${tone}`}>{children}</span>;
}

function Toggle({ on = false, onClick }: { on?: boolean; onClick?: () => void }) {
  return <button aria-label={on ? "Desativar" : "Ativar"} className={`switch ${on ? "on" : ""}`} onClick={onClick} />;
}

function Modal({ title, description, children, onClose }: { title: string; description?: string; children: ReactNode; onClose: () => void }) {
  return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="modal" role="dialog" aria-modal="true"><div className="modal-header"><div><h2 className="modal-title">{title}</h2>{description && <p className="modal-description">{description}</p>}</div><button className="close" onClick={onClose} aria-label="Fechar"><X size={16} /></button></div><div className="modal-body">{children}</div></div></div>;
}

